
package com.richfield.smartpantry;
import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;
// Provides the add/edit ingredient form, validates input, and saves or deletes pantry items.
public class EditIngredientActivity extends BaseActivity {DatabaseHelper db;Ingredient current;EditText name,qty,unit,expiry;@Override public void onCreate(Bundle b){super.onCreate(b);db=new DatabaseHelper(this);long id=getIntent().getLongExtra("id",-1);current=id<0?null:db.ingredient(id);form();} EditText field(LinearLayout r,String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setInputType(type);r.addView(e);return e;}void form(){LinearLayout r=page(current==null?"Add ingredient":"Edit ingredient");name=field(r,"Ingredient name (e.g. tomatoes)",InputType.TYPE_CLASS_TEXT);qty=field(r,"Quantity",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);unit=field(r,"Unit: each, g, kg, ml or l",InputType.TYPE_CLASS_TEXT);expiry=field(r,"Expiry date (optional, e.g. 2026-10-01)",InputType.TYPE_CLASS_TEXT);if(current!=null){name.setText(current.name);qty.setText(""+current.quantity);unit.setText(current.unit);expiry.setText(current.expiry);}Button save=button("Save ingredient");save.setOnClickListener(v->save());r.addView(save);if(current!=null){Button del=button("Delete ingredient");del.setOnClickListener(v->{db.deleteIngredient(current.id);finish();});r.addView(del);}setContentView(r);}void save(){String n=name.getText().toString().trim(),q=qty.getText().toString().trim(),u=unit.getText().toString().trim();if(n.isEmpty()||q.isEmpty()||u.isEmpty()){Toast.makeText(this,"Name, quantity and unit are required.",Toast.LENGTH_LONG).show();return;}try{double d=Double.parseDouble(q);if(d<=0)throw new NumberFormatException();db.saveIngredient(new Ingredient(current==null?-1:current.id,n,d,u,expiry.getText().toString().trim()));finish();}catch(NumberFormatException e){qty.setError("Enter a quantity greater than zero");}}}
